async function o(e,r={},t){return window.__TAURI_INTERNALS__.invoke(e,r,t)}const n=new Map,p={getProviders(){return o("get_providers")},search(e,r=0,t=20){return o("search",{keyword:e,skip:r,take:t})},getEntity(e){return o("get_entity",{url:e})},getChapter(e,r){return o("get_chapter",{entityUrl:e,chapterUrl:r})},getImageUrl(e,r){const t=`${e}|${r}`;return n.has(t)?n.get(t):(o("get_image",{entityUrl:e,url:r}).then(a=>{const u=new Blob([new Uint8Array(a)],{type:"image/png"}),s=URL.createObjectURL(u);n.set(t,s),window.dispatchEvent(new CustomEvent("tauri-image-loaded",{detail:{key:t,url:s}}))}).catch(console.error),"")},getProposal(e,r=20){return o("get_proposal",{engineName:e,take:r})},getBookshelf(){return o("get_bookshelf")},addToBookshelf(e){return o("add_to_bookshelf",{url:e.url,name:e.name,imageUrl:e.image_url,descript:e.descript,chaptersCount:e.chapters_count})},removeFromBookshelf(e){return o("remove_from_bookshelf",{url:e})},updateReadingProgress(e,r,t){return o("update_reading_progress",{url:e,chapter:r,page:t})}};export{p as tauriAdapter};
